-- palashroy.me content database schema + seed
-- Import this in phpMyAdmin (into your new database).

CREATE TABLE IF NOT EXISTS `content` (
  `section` VARCHAR(50) NOT NULL PRIMARY KEY,
  `data` LONGTEXT NOT NULL,
  `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `admin_users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `failed_attempts` INT NOT NULL DEFAULT 0,
  `locked_until` INT NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Seed content
INSERT INTO `content` (`section`,`data`) VALUES ('publications', '[{"title": "Carbon-Taxed Transformers: A Green Compression Pipeline for Overgrown Language Models", "authors": "A. I. Alam, P. R. Roy, C. K. Roy, B. Roy and K. A. Schneider", "venue": "Proceedings of the ACM on Software Engineering (PACMSE), FSE 2026", "year": "2026", "pages": "pp. 1035-1058", "award": "ACM SIGSOFT Distinguished Paper Award", "description": "Winner of the ACM SIGSOFT Distinguished Paper Award. Introduces Carbon-Taxed Transformers (CTT), a green compression pipeline inspired by carbon-taxation economics that achieves up to 49x memory reduction and up to 81% lower CO2 emissions while retaining roughly 98% clone-detection accuracy across multiple transformer architectures.", "preprint": "/papers/CTT.pdf"}, {"title": "Carbon-Taxed Transformers: Efficient, Accurate, and Sustainable LLMs", "authors": "A. I. Alam, P. R. Roy, C. K. Roy, B. Roy and K. A. Schneider", "venue": "34th ACM International Conference on the Foundations of Software Engineering (FSE), Poster Track", "year": "2026", "description": "A poster summarizing Carbon-Taxed Transformers (CTT), a pipeline for efficient, accurate, and sustainable large language models applied to software engineering tasks."}, {"title": "Are Classical Clone Detectors Good Enough For the AI Era?", "authors": "A. I. Alam, P. R. Roy, F. Al-omari, C. K. Roy, B. Roy and K. A. Schneider", "venue": "2025 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "year": "2025", "pages": "pp. 295-307", "doi": "10.1109/ICSME64153.2025.00035", "description": "Evaluates the effectiveness of classical clone detection tools in the modern AI era, analyzing their performance against AI-generated code and proposing improvements for contemporary software development.", "preprint": "https://arxiv.org/pdf/2509.25754"}, {"title": "Towards Just-In-Time, Inclusive Clone Refactoring", "authors": "P. Roy", "venue": "2025 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "year": "2025", "pages": "pp. 884-886", "doi": "10.1109/ICSME64153.2025.00099", "description": "Proposes a just-in-time approach to clone refactoring that is inclusive and automated, leveraging large language models and RAG techniques for trustworthy code maintenance.", "preprint": "/papers/Towards_Just-In-Time_Inclusive_Clone_Refactoring.pdf"}, {"title": "Gptclonebench: A comprehensive benchmark of semantic clones and cross-language clones using gpt-3 model and semanticclonebench", "authors": "A. I. Alam, P. R. Roy, F. Al-Omari, C. K. Roy, B. Roy, and K. A. Schneider", "venue": "2023 IEEE International Conference on Software Maintenance and Evolution (ICSME)", "year": "2023", "pages": "pp. 1-13", "doi": "10.1109/ICSME58846.2023.00013", "description": "Presents a benchmark for evaluating semantic code clones and cross-language clones generated using GPT-3.", "preprint": "/papers/gptclonebench.pdf"}, {"title": "Unveiling the potential of large language models in generating semantic and cross-language clones", "authors": "P. R. Roy, A. I. Alam, F. Al-omari, B. Roy, C. K. Roy, and K. A. Schneider", "venue": "2023 IEEE 17th International Workshop on Software Clones (IWSC)", "year": "2023", "pages": "pp. 22-28", "doi": "10.1109/IWSC60764.2023.00011", "description": "Explores how large language models can generate semantic code clones and cross-language clones, analyzing their potential applications and implications.", "preprint": "/papers/unveling_potential.pdf"}, {"title": "A study on paper and author ranking", "authors": "P. R. Roy, M. N. Islam, L. T. Jeba, et al.", "venue": "2022 International Conference on Innovations in Science, Engineering and Technology (ICISET)", "year": "2022", "pages": "pp. 545-549", "doi": "10.1109/ICISET54810.2022.9775821", "description": "Examines methodologies for ranking academic papers and authors, analyzing citation patterns and impact metrics in scientific literature.", "preprint": "/papers/A_Study_on_Paper_and_Author_Ranking.pdf"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('highlights', '[{"title": "🏆 ACM SIGSOFT Distinguished Paper Award (2026)", "organization": "ACM International Conference on the Foundations of Software Engineering (FSE)", "description": "Awarded to \\"Carbon-Taxed Transformers: A Green Compression Pipeline for Overgrown Language Models\\" (FSE 2026), one of the highest honors for a paper at a flagship software engineering conference."}, {"title": "Research Excellence in Science, Technology, Engineering, or Math (2025)", "organization": "Graduate Students Association, University of Saskatchewan", "description": "Recognized for outstanding contributions to research in STEM fields at the university level.", "link": "https://www.cs.usask.ca/news/2025/celebrating-excellence-computer-science-professor-and-graduate-students-receive-gsa-awards.php"}, {"title": "Best Thesis Award (MSc) (2025)", "organization": "Department of Computer Science, University of Saskatchewan", "description": "Awarded for exceptional research work during Master''s studies in Computer Science."}, {"title": "SOAR Distinguished Research Award (2024)", "organization": "NSERC Collaborative Research and Training (CREATE), Canada", "description": "Recognized for distinguished research contributions within the NSERC collaborative framework."}, {"title": "75th Anniversary Scholarship (2024)", "organization": "College of Graduate & Postdoctoral Studies (CGPS), University of Saskatchewan", "description": "Received scholarship commemorating the 75th anniversary of the College of Graduate Studies."}, {"title": "CS Citizenship Award (M.Sc.) (2024)", "organization": "Department of Computer Science, University of Saskatchewan", "description": "Recognized for exemplary citizenship and community contributions within the Computer Science department.", "link": "https://www.cs.usask.ca/news/2024/graduate-student-award-recipients.php"}, {"title": "Research Award (2024)", "organization": "8th Symposium on Innovations in Computer Science and Applied Computing (ICSAC), University of Saskatchewan", "description": "Awarded for innovative research presented at the ICSAC symposium."}, {"title": "People''s Choice Best Paper Award (2023)", "organization": "IWSC-2023 at Bogota, Colombia", "description": "Paper on large language models and code clones voted as the best paper by attendees.", "link": "https://news.usask.ca/articles/colleges/2023/usask-clones-researcher-wins-international-award.php"}, {"title": "Student Encouragement Award (2023)", "organization": "IWSC-2023 at Bogota, Colombia", "description": "Received encouragement award at the International Workshop on Software Clones in Bogota.", "link": "https://news.usask.ca/articles/colleges/2023/usask-clones-researcher-wins-international-award.php"}, {"title": "People''s Choice Best Presentation Award (2023)", "organization": "SOAR Symposium at Saskatoon, Saskatchewan", "description": "Presentation voted as the best by symposium attendees at the SOAR event in Saskatoon."}, {"title": "Nominated for University of Saskatchewan Best Thesis Award (2025)", "organization": "College of Graduate and Postdoctoral Studies, University of Saskatchewan", "description": "Thesis nominated for the prestigious university-wide best thesis recognition."}, {"title": "Nominated for WAGS Distinguished MSc Thesis STEM (2025)", "organization": "Western Association of Graduate School", "description": "Thesis nominated for distinguished recognition among STEM disciplines across Western institutions."}, {"title": "Nominee, CS Geddes Awards (M.Sc.) (2024)", "organization": "Department of Computer Science, University of Saskatchewan", "description": "Nominated for the prestigious Geddes Award for excellence in Computer Science."}, {"title": "Nominee, Carl McCrosky Innovation Scholarship (2024)", "organization": "University of Saskatchewan", "description": "Nominated for scholarship recognizing innovative approaches in Computer Science research."}, {"title": "Nominee, Mark Kroeker Exceptional Student Leadership Award (2024)", "organization": "University of Saskatchewan", "description": "Nominated for exceptional leadership within the student community."}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('news', '[{"date": "2026", "icon": "🏆", "title": "Won the ACM SIGSOFT Distinguished Paper Award at FSE 2026", "description": "\\"Carbon-Taxed Transformers\\" was recognized as a Distinguished Paper, one of the highest honors at a flagship software engineering conference."}, {"date": "2026", "icon": "📄", "title": "Published at FSE 2026 (paper and poster)", "description": "Carbon-Taxed Transformers appeared as a full research paper and a poster at the ACM International Conference on the Foundations of Software Engineering."}, {"date": "2025-2026", "icon": "🎓", "title": "Serving as President of the USask Graduate Students'' Association", "description": "Elected to represent more than 4,500 graduate students, and appointed to the University Senate and Provost Search Committee."}, {"date": "2025", "icon": "🏅", "title": "Received the GSA Research Excellence Award (STEM)", "description": "Recognized for outstanding research contributions in science, technology, engineering, and math at the University of Saskatchewan."}, {"date": "2025", "icon": "🎓", "title": "Awarded Best Thesis (MSc) in Computer Science", "description": "Honored for exceptional research during Master''s studies at the University of Saskatchewan."}, {"date": "2023", "icon": "🥇", "title": "Won the People''s Choice Best Paper Award at IWSC 2023", "description": "Paper on large language models and code clones voted best by attendees at the International Workshop on Software Clones in Bogota, Colombia."}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('media', '[{"outlet": "University of Saskatchewan, Computer Science", "date": "2025", "title": "Celebrating Excellence: Computer Science professor and graduate students receive GSA awards", "url": "https://www.cs.usask.ca/news/2025/celebrating-excellence-computer-science-professor-and-graduate-students-receive-gsa-awards.php"}, {"outlet": "USask News", "date": "2023", "title": "USask clones researcher wins international award", "url": "https://news.usask.ca/articles/colleges/2023/usask-clones-researcher-wins-international-award.php"}, {"outlet": "University of Saskatchewan, Computer Science", "date": "2024", "title": "Graduate Student Award Recipients", "url": "https://www.cs.usask.ca/news/2024/graduate-student-award-recipients.php"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('gallery', '[{"image": "/images/gsa_gala/gala-final-speech.jpg", "title": "Final Address as GSA President", "description": "Delivering my final address as President of the University of Saskatchewan Graduate Students'' Association at the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy (Palash Roy) delivering his final speech as GSA President at the 2026 University of Saskatchewan Graduate Students'' Association Awards and Gala"}, {"image": "/images/gsa_gala/gala-awards-stage.jpg", "title": "Presenting the GSA Awards", "description": "Recognizing outstanding graduate students on stage during the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy presenting awards to graduate student recipients on stage at the 2026 University of Saskatchewan GSA Awards and Gala"}, {"image": "/images/gsa_gala/gala-cgps-dean-burshtyn.jpg", "title": "With CGPS Dean Dr. Deborah Burshtyn", "description": "With Dr. Deborah (Debby) Burshtyn, Dean of the College of Graduate and Postdoctoral Studies (CGPS), at the 2026 GSA Awards & Gala.", "altText": "Palash Roy with Dr. Deborah Burshtyn, Dean of the College of Graduate and Postdoctoral Studies, at the 2026 University of Saskatchewan GSA Awards and Gala"}, {"image": "/images/gsa_gala/gala-vice-provost-delbaere.jpg", "title": "With Vice-Provost Dr. Marjorie Delbaere", "description": "With Dr. Marjorie Delbaere, Interim Vice-Provost, Students and Learning, at the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy with Dr. Marjorie Delbaere, Interim Vice-Provost Students and Learning, at the 2026 University of Saskatchewan GSA Awards and Gala"}, {"image": "/images/gsa_gala/gala-medicine-dean.jpg", "title": "With Medicine Dean Dr. Sarah Forgie", "description": "With Dr. Sarah Forgie, Dean of the College of Medicine, University of Saskatchewan, at the 2026 GSA Awards & Gala.", "altText": "Palash Roy with Dr. Sarah Forgie, Dean of the College of Medicine, at the 2026 University of Saskatchewan GSA Awards and Gala"}, {"image": "/images/gsa_gala/gala-provost-mcdougall.jpg", "title": "With Provost Dr. Patti McDougall", "description": "With Dr. Patti McDougall, Interim Provost and Vice-President Academic, at the 2026 GSA Awards & Gala.", "altText": "Palash Ranjan Roy with Dr. Patti McDougall, Interim Provost and Vice-President Academic, at the 2026 University of Saskatchewan GSA Awards and Gala"}, {"image": "/images/gsa_gala/gala-executive-team.jpg", "title": "The GSA Executive Team", "description": "With the University of Saskatchewan GSA executive team at the 2026 Awards & Gala.", "altText": "Palash Roy with the University of Saskatchewan Graduate Students'' Association executive team at the 2026 GSA Awards and Gala"}, {"image": "/images/gsa_gala/gala-team-celebration.jpg", "title": "Celebrating with the Team", "description": "Celebrating a successful year with the GSA team at the 2026 Awards & Gala.", "altText": "Palash Ranjan Roy celebrating with the University of Saskatchewan GSA team at the 2026 GSA Awards and Gala"}, {"image": "/images/Pic_section/Palash-Roy_Plaza de Bolívar.jpg", "title": "Plaza de Bolívar, Colombia", "description": "Exploring the historic heart of Bogotá at Plaza de Bolívar during my research visit for ICSME-2023.", "altText": "Palash Ranjan Roy (Palash Roy) at Plaza de Bolívar in Bogotá during ICSME-2023 research conference"}, {"image": "/images/Pic_section/Palash-Justin_Santa Fe, Bogotá, Chocó.jpg", "title": "Santa Fe, Bogotá, Chocó", "description": "Making connections with fellow researchers in beautiful Colombia during our conference travel.", "altText": "Palash Roy with Justin in Santa Fe, Bogotá, Chocó - Computer Science researchers at international conference"}, {"image": "/images/Pic_section/Palash_Group_Chico_Norte.jpg", "title": "Group Photo at Chico Norte", "description": "Exploring Chico Norte fellow friends of mine from all over the world.", "altText": "Palash Ranjan Roy with international research colleagues at Chico Norte in Colombia"}, {"image": "/images/Pic_section/Palash-Group_Parque_Nacional_Oriental.jpg", "title": "Parque Nacional Oriental", "description": "Taking a break from academic discussions to enjoy Colombia''s natural beauty at Parque Nacional Oriental.", "altText": "Palash Roy with research colleagues at Parque Nacional Oriental in Colombia during academic conference"}, {"image": "/images/Pic_section/Palash-Cousins_Banff_Gondola.jpg", "title": "Banff Gondola with Cousins", "description": "Enjoying the breathtaking views of the Canadian Rockies with family at the Banff Gondola.", "altText": "PhD student Palash Ranjan Roy with cousins at Banff Gondola in the Canadian Rockies"}, {"image": "/images/Pic_section/Palash-Cousins2_banff.jpg", "title": "Banff National Park", "description": "Another memorable moment with cousins exploring the natural wonders of Banff National Park.", "altText": "Palash Roy and cousins visiting Banff National Park in Alberta, Canada"}, {"image": "/images/Pic_section/Palash-Family_Sulphur_Mountain.jpg", "title": "Family at Sulphur Mountain", "description": "A family adventure scaling the heights of Sulphur Mountain with its spectacular panoramic views.", "altText": "Computer Science researcher Palash Ranjan Roy with family at Sulphur Mountain in Banff, Canada"}, {"image": "/images/Pic_section/Palash-Mugdho(Cousin)_Montauk_Point_State_Park.jpg", "title": "Montauk Point State Park", "description": "An enjoyable day with my cousin Mugdho at Montauk Point State Park, taking in the coastal scenery.", "altText": "Palash Roy and cousin Mugdho at Montauk Point State Park in New York"}, {"image": "/images/Pic_section/Palash-Roy_West_Village_NY(Friends_Building).jpg", "title": "West Village, New York", "description": "Couldn''t resist visiting the iconic ''Friends'' building during my trip to West Village, New York!", "altText": "Palash Ranjan Roy visiting the Friends TV show building in West Village, New York City"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('leadership', '[{"period": "2025-2026", "role": "President", "organization": "Graduate Students Association (GSA)", "place": "University of Saskatchewan", "link": "https://gsa.usask.ca"}, {"period": "2024-2025", "role": "President", "organization": "Bangladeshi Students'' Association (BSAUS)", "place": "University of Saskatchewan"}, {"period": "2023-2024", "role": "Vice President Finance", "organization": "Computer Science Graduate Council", "place": "University of Saskatchewan"}, {"period": "2022-2023", "role": "Vice President Social", "organization": "Computer Science Graduate Council", "place": "University of Saskatchewan"}, {"period": "2018-2021", "role": "Assistant General Secretary", "organization": "Robotics Club Of Brac University [ROBU]", "place": "BRAC University"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('service', '[{"period": "2025-2026", "role": "Senate Member", "description": "Served as a member of the University Senate, contributing to university-wide governance and academic policy.", "venue": "University of Saskatchewan"}, {"period": "2026-2027", "role": "Search Committee Member", "description": "Committee member for the Provost and Vice-President Academic Search Committee.", "venue": "University of Saskatchewan"}, {"period": "2025-2026", "role": "Governance Committee Member", "description": "Served on a University Governance Committee as part of graduate student leadership.", "venue": "University of Saskatchewan"}, {"period": "2025-2026", "role": "Award Committee Member", "description": "Served on multiple University of Saskatchewan award selection committees, including the Distinguished Researcher Award.", "venue": "University of Saskatchewan"}, {"period": "2025-2026", "role": "CGPS Committee Member", "description": "Served on College of Graduate and Postdoctoral Studies (CGPS) committees, and presented graduate-student reports to University Council and college/faculty councils.", "venue": "University of Saskatchewan"}, {"period": "2026-Present", "role": "Graduate Peer Mentor", "description": "Helping new graduate students navigate grad life through the Peer Assisted Learning (PAL) program, delivering small-group workshops and one-to-one sessions on academic skills and the transition into graduate studies.", "venue": "University of Saskatchewan"}, {"period": "2022-Present", "role": "Peer Reviewer", "description": "Reviewed multiple Software Engineering conferences and Journal submissions", "venues": "ICSME, ASE, SCAM, SANER, MSR, JSS, TSE, and TOSEM"}, {"period": "Spring-Summer 2024", "role": "Research Supervision", "description": "Supervised one undergraduate research student who won two undergraduate research excellence awards at ICSAC-24 and SOAR Symposium 2024", "venue": "Software Research lab & Interactive Software Engineering Lab, University of Saskatchewan"}, {"period": "Spring-Summer 2023", "role": "Research Supervision", "description": "Supervised six undergraduate research students", "venue": "Software Research lab & Interactive Software Engineering Lab, University of Saskatchewan"}, {"period": "2025", "role": "Invited Speaker", "description": "Large language models and Code Similarity", "venue": "Thompson Rivers University"}, {"period": "2024", "role": "Invited Speaker", "description": "AI for Software Engineering", "venue": "University of Saskatchewan"}, {"period": "2024", "role": "Invited Speaker", "description": "The Effects of Visual Embellishment on Comprehension and Memorability of Charts", "venue": "University of Saskatchewan"}, {"period": "2023", "role": "Invited Speaker", "description": "Software Engineering in Practice", "venue": "BRAC University"}, {"period": "2022", "role": "Invited Speaker", "description": "How to start building your first Robot?", "venue": "BRAC University"}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('references', '[{"name": "Rezwana Mahfuza", "title": "PhD Student, Dalhousie University", "image": "/images/rezwana.jpg", "text": "Palash was an integral part of my study environment when I first started university at Brac University. Palash spent time with me not just to assist me with day-to-day tasks, but also to encourage me with many academic endeavors over the years. He inspires his team, provides important input, and works for everyone to achieve better as a groupmate."}, {"name": "Farishta Kabir", "title": "Graduate Research and Teaching Assistant, University of Alberta", "image": "/images/farishta.jpg", "text": "I''ve had the pleasure of working with Palash during a few undergraduate courses and in the Robotics Club at BRAC University as a colleague. He always stood-out for his focused problem-solving approach and leadership in teamwork. Palash combines his expertise with an organizational mindset, making him a productive addition to any research project or team. Wishing him all the best for his future endeavours."}, {"name": "Fahmida Nipa", "title": "PS & CS Core Network, Cyber Security, Datacom", "image": "/images/Nipa.jpg", "text": "Throughout my Robotics Club journey, I have seen Palash to be very enthusiastic about robotics. Not to mention the leadership and managerial quality I got to experience while working with him was quite mentionable. I believe he will do his best wherever he set his foot, as his dignity towards his responsibilities resembles how much effort he can demonstrate. He is very adaptive and can communicate fluently with anyone when working in teams. I personally teamed up with him during several events organized by the club. those works were success and naturally outstanding as he pulled out the best from the team."}, {"name": "Syeda Umme Salma", "title": "Graduate Research Assistant, PhD Student", "image": "/images/omi.jpg", "text": "Palash is one of the greatest guys I''ve ever had as a collaborator, and we''ve worked together on multiple projects. I would strongly suggest his services to anyone in need of an software engineer. He is one of the wisest persons I have ever encountered, and his ability to solve any situation with a pleasant gesture is astonishing. Palash would be a valuable addition to any team."}, {"name": "Md. Noushin Islam", "title": "Web Developer, Frontend Developer, MSc in Software Engineering", "image": "/images/saad.jpg", "text": "I was impressed by Palash''s ability to handle any situation calmly and patiently, even in the toughest situation. His natural skill has helped us succeed in many events throughout my journey at ROBU."}]')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
INSERT INTO `content` (`section`,`data`) VALUES ('metrics', '{"citations": 31, "hIndex": 3, "works": 15, "source": "OpenAlex", "openAlexId": "A5058812722", "profileUrl": "https://openalex.org/A5058812722", "updated": "2026-07-23"}')
  ON DUPLICATE KEY UPDATE `data`=VALUES(`data`);
